-- Phase 6U-B3-P (P-1): bind S3 multipart upload ID to server-created reservation.\n--\n-- WHY\n--\n-- The per-part signing action (requestMultipartPartUrl) derives the stagingKey\n-- from the reservation row, which already binds the object key to the server-\n-- created session. However, the S3 multipartUploadId was not persisted, so\n-- the client could pass arbitrary values and the server would sign URLs for\n-- them, potentially creating unbounded arm rows for the same reservation.\n--\n-- This column ensures the multipartUploadId is the ONE the server created\n-- for this reservation. The action validates that the requested partNumber is\n-- within 1..multipartPartCount(sizeBytes) and that the reservation has a\n-- non-null multipartUploadId before signing.\n--\n-- SAFETY: The column is nullable, so existing reservations (single-mode or\n-- already completed) remain valid. New reservations always get a value set\n-- when createMultipartUpload succeeds.\n--\n-- Rollback: ALTER TABLE "attachment_upload_reservations" DROP COLUMN "multipart_upload_id";\n\nALTER TABLE "attachment_upload_reservations" ADD COLUMN "multipart_upload_id" text;